mapper.select:
SELECT p.PTL_GRP_CD AS ptlGrpCd, p.PTL_CD AS ptlCd, p.PTL_TYPE AS ptlType, COALESCE(tl.RES_VAL, td.COM_NM) AS ptlTypeNm, p.PTL_LEN AS ptlLen, COALESCE(ml.RES_VAL, d.PTL_NM) AS ptlNm, COALESCE(md.RES_VAL, d.PTL_DESC) AS ptlDesc, p.USE_YN AS useYn, (SELECT COUNT(*) FROM ju_protocol_packet k WHERE k.PTL_GRP_CD = p.PTL_GRP_CD AND k.PTL_CD = p.PTL_CD AND k.USE_YN = 'YENO0001') AS packetCount FROM ju_protocol p LEFT JOIN ju_protocol_detail d ON d.PTL_GRP_CD = p.PTL_GRP_CD AND d.PTL_CD = p.PTL_CD LEFT JOIN ju_multi_lang ml ON ml.LANG_CD = #{langCd} AND ml.RES_KEY = d.PTL_NM_KEY LEFT JOIN ju_multi_lang md ON md.LANG_CD = #{langCd} AND md.RES_KEY = d.PTL_DESC_KEY LEFT JOIN ju_com_code_detail td ON td.GRP_CD = 'PROT' AND td.COM_CD = p.PTL_TYPE LEFT JOIN ju_multi_lang tl ON tl.LANG_CD = #{langCd} AND tl.RES_KEY = td.COM_NM_KEY WHERE p.PTL_GRP_CD = #{ptlGrpCd}
AND (p.PTL_CD LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(ml.RES_VAL, d.PTL_NM) LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.PTL_CD

mapper.update:
UPDATE ju_protocol_detail
   SET PTL_NM   = COALESCE(#{ptlNm,jdbcType=VARCHAR}, PTL_NM),
       PTL_DESC = COALESCE(#{ptlDesc,jdbcType=VARCHAR}, PTL_DESC)
 WHERE PTL_GRP_CD = #{ptlGrpCd}
   AND PTL_CD = #{ptlCd}
